# py_manifest — read a value from the run manifest. Args: dotted key or expression.
py_manifest() {
  ( cd "$REPO" && "$VENV_PY" - "$RUN_DIR" "$1" <<'PY'
import json, pathlib, sys
run, expr = pathlib.Path(sys.argv[1]), sys.argv[2]
m = json.loads((run / "runtime/manifest.json").read_text(encoding="utf-8"))
print(eval(expr, {"m": m, "json": json}))
PY
  )
}

# py_db SNIPPET — run a Python snippet against the run's isolated MySQL schema.
# The snippet travels as a single argv entry (a quoted heredoc at each call site)
# so SQL quoting survives; `rows()`, `m`, `db` and `json` are in scope.
py_db() {
  ( cd "$REPO" && WIZARD_ADMIN_URL="$REAL_SERVICES_MYSQL_ADMIN_URL" "$VENV_PY" - "$RUN_DIR" "$1" <<'PY'
import json, os, pathlib, sys
from sqlalchemy import create_engine, text
run, code = pathlib.Path(sys.argv[1]), sys.argv[2]
m = json.loads((run / "runtime/manifest.json").read_text(encoding="utf-8"))
engine = create_engine(os.environ["WIZARD_ADMIN_URL"] + "/" + m["schema"] + "?charset=utf8mb4")
try:
    with engine.connect() as db:
        rows = lambda sql: [dict(r) for r in db.execute(text(sql)).mappings()]
        exec(code, {"db": db, "m": m, "rows": rows, "json": json, "print": print})
finally:
    engine.dispose()
PY
  )
}

# wait_http URL LABEL [PID] — block until a local service answers. Fails fast if
# the optional PID we launched has already exited (a crashed startup would
# otherwise burn the whole timeout).
wait_http() {
  local url="$1" label="$2" pid="${3:-}" i
  for i in $(seq 1 120); do
    if curl -fsS --max-time 2 "$url" >/dev/null 2>&1; then
      printf '  %s✓%s %s ready\n' "$GREEN" "$RESET" "$label"
      return 0
    fi
    if [[ -n "$pid" ]] && ! kill -0 "$pid" 2>/dev/null; then
      warn "$label 的启动进程已退出，先看日志再继续：$WINDOW_LOG"
      return 1
    fi
    sleep 2
  done
  warn "$label did not answer at $url"
  return 1
}

# expect "question" SNIPPET — poll a py_db assertion, letting the human fix it in
# the browser (the Worker often needs another few seconds). A skipped check is
# recorded, never fatal: the run must still close out so gathered evidence
# survives. The snippet is passed as a plain string, not eval'd.
expect() {
  local question="$1" snippet="$2" out
  while ! out=$(py_db "$snippet" 2>&1); do
    warn "还没有检测到预期的状态（可能是后台 Worker 还没跑完）。"
    note "$out"
    if confirm "$question"; then continue; fi
    warn "跳过该检查 — 本轮证据将缺少这一项，报告里会体现。"
    SKIPPED+=("未验证：$question")
    return 0
  done
  printf '  %s✓ verified%s %s\n' "$GREEN" "$RESET" "$out"
}

