step "点“领取最终临床复核”，选择“确认 AI 评估”，提交。"
say ""
note "解释只有在参考资料审核通过、且来源校验一致时才会发布；如果任务落到“结果受限”，"
note "先检查第 2 阶段的三份资料。"
FINAL_CHECK=$(cat <<SNIPPET
workflow = rows("SELECT status, explanationPublicationStatus FROM t_diagnosis_workflow "
                "WHERE workflowId = '$W1'")[0]
review = rows("SELECT decisionCode, status FROM t_human_review_task "
              "WHERE workflowId = '$W1' AND reviewType = 'FINAL_CLINICAL_REVIEW'")
if not review:
    raise SystemExit("workflow=" + workflow["status"] + ", no final clinical review task yet")
if review[0]["status"] != "SUBMITTED" or review[0]["decisionCode"] != "CONFIRM_AI_ASSESSMENT":
    raise SystemExit("workflow=" + workflow["status"] + ", final review " + review[0]["status"])
if workflow["status"] != "COMPLETED":
    raise SystemExit("final review submitted but workflow is " + workflow["status"]
                     + " (publication=" + str(workflow["explanationPublicationStatus"]) + ")")
print("workflow COMPLETED, final review CONFIRM_AI_ASSESSMENT")
SNIPPET
)
expect "任务 A 已显示“处理完成”，且最终复核已提交了吗？" "$FINAL_CHECK"

# ═══ Stage 6 ═══════════════════════════════════════════════════════════════
stage "AC-09 拒绝保存（任务 A）" 4
say "现在换回患者，走一次“拒绝保存”，证明拒绝后不产生正式诊断记录。"
open_url "http://127.0.0.1:5173/user/login"
step "退出医生账号，用患者账号 $PATIENT_ACCOUNT 登录。"
step "打开 http://127.0.0.1:5173/diagnosis?workflow=$W1"
step "在“正式诊断保存”区域点“查看拟保存内容”，确认预览里有图片、解释和参考来源。"
step "点“拒绝保存”。"
step "确认页面显示“您已拒绝保存，未建立正式记录”。"
say ""
REJECT_CHECK=$(cat <<SNIPPET
confirmations = rows("SELECT status FROM t_diagnosis_save_confirmation "
                     "WHERE workflowId = '$W1' ORDER BY requestVersion")
records = rows("SELECT COUNT(*) AS n FROM t_saved_workflow_diagnosis WHERE workflowId = '$W1'")[0]["n"]
if not confirmations:
    raise SystemExit("no save confirmation yet")
if confirmations[-1]["status"] != "REJECTED" or records != 0:
    raise SystemExit("confirmation=" + confirmations[-1]["status"] + ", formal records=" + str(records))
print("confirmation REJECTED, formal records 0")
SNIPPET
)
expect "任务 A 的保存确认是 REJECTED，且没有正式记录吗？" "$REJECT_CHECK"

# ═══ Stage 7 ═══════════════════════════════════════════════════════════════
stage "AC-11 质量复核（任务 B）" 4
say "任务 B（0_left.jpg，cataract）置信度较高，不需要最终临床复核；质量通过后会直接发布解释。"
step "退出患者账号，用医生账号 $DOCTOR_ACCOUNT 登录，进入 医生复核。"
step "点“刷新复核任务”，找到任务号 $W0 的“图像质量”任务。"
step "点“领取质量复核”，选择“允许复用原推理包继续”，提交。"
say ""
QB_CHECK=$(cat <<SNIPPET
workflow = rows("SELECT status, explanationPublicationStatus FROM t_diagnosis_workflow "
                "WHERE workflowId = '$W0'")[0]
if workflow["status"] != "COMPLETED" or workflow["explanationPublicationStatus"] != "PUBLISHED":
    raise SystemExit("workflow=" + workflow["status"] + ", publication="
                     + str(workflow["explanationPublicationStatus"]))
print("workflow COMPLETED, explanation PUBLISHED")
SNIPPET
)
expect "任务 B 已“处理完成”且解释已发布了吗？" "$QB_CHECK"

# ═══ Stage 8 ═══════════════════════════════════════════════════════════════
stage "AC-09 批准保存（任务 B）" 4
step "退出医生账号，用患者账号 $PATIENT_ACCOUNT 登录。"
step "打开 http://127.0.0.1:5173/diagnosis?workflow=$W0"
step "点“查看拟保存内容”，核对预览内容。"
step "点“批准并保存正式诊断”。"
step "记下页面显示的记录编号。"
say ""
APPROVE_CHECK=$(cat <<SNIPPET
confirmations = rows("SELECT status FROM t_diagnosis_save_confirmation "
                     "WHERE workflowId = '$W0' ORDER BY requestVersion")
saved = rows("SELECT diagnosisId FROM t_saved_workflow_diagnosis WHERE workflowId = '$W0'")
if not confirmations:
    raise SystemExit("no save confirmation yet")
if confirmations[-1]["status"] != "APPROVED" or not saved:
    raise SystemExit("confirmation=" + confirmations[-1]["status"] + ", formal records=" + str(len(saved)))
print("diagnosisId", saved[0]["diagnosisId"])
SNIPPET
)
expect "任务 B 已显示“正式诊断记录已保存”并给出记录编号了吗？" "$APPROVE_CHECK"
step "再打开 个人中心 → 诊断历史，确认这条记录可查。"

# ═══ Stage 9 ═══════════════════════════════════════════════════════════════
stage "AC-21 完整 UI 走查" 4
say "最后把前端主路径自己走一遍，确认没有界面级断点。"
step "聊天：/agent 发一条普通消息，确认流式回复正常结束。"
step "上传：/diagnosis 选一张 jpg/png，确认任务进入等待或完成状态。"
step "刷新：在任务页按 F5，确认任务状态和保存区仍在。"
step "诊断历史：确认记录、详情、趋势图可打开。"
step "医生复核：确认列表与详情不再有待领取的旧任务异常。"
say ""
if confirm "上面五项都走通了吗？（选 n 表示仍有界面问题）"; then
  UI_WALKTHROUGH="PASS"
  printf '  %s✓%s AC-21 人工走查记为 PASS\n' "$GREEN" "$RESET"
else
  UI_WALKTHROUGH="BLOCKED"
  warn "AC-21 人工走查记为 BLOCKED，原因会写进参与记录。"
fi

# ═══ Stage 10 ═══════════════════════════════════════════════════════════════
stage "收尾：保存证据并生成报告" 6
say "结束人工窗口，导出观察快照，再生成汇总报告。"
pause "确认浏览器里的操作都做完了，按 Enter 收尾"

note "通知人工窗口结束…"
touch "$RUN_DIR/runtime/finish-manual-window"
if [[ -n "$WINDOW_PID" ]]; then
  for i in $(seq 1 90); do
    kill -0 "$WINDOW_PID" 2>/dev/null || break
    sleep 2
  done
fi
if [[ -n "$WINDOW_PID" ]] && kill -0 "$WINDOW_PID" 2>/dev/null; then
  warn "人工窗口进程仍在运行；等它自己退出后再跑 summary。"
else
  printf '  %s✓%s 人工窗口已退出，进程已清理\n' "$GREEN" "$RESET"
fi

say ""
note "写人工参与记录…"
cat > "$RUN_DIR/manual-participation.json" <<JSON
{
  "status": "EXECUTED",
  "date": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "scope": "AC-08 supplement resume, AC-09 approve/refuse save, AC-11 quality and final clinical review, AC-21 full UI walkthrough",
  "uiWalkthrough": "$UI_WALKTHROUGH",
  "participant": "human operator at the browser; no script submitted any clinical or consent decision",
  "decisionsDelegated": false,
  "unverifiedChecks": $(printf '%s\n' "${SKIPPED[@]:-}" | "$VENV_PY" -c 'import json,sys; print(json.dumps([l for l in sys.stdin.read().splitlines() if l], ensure_ascii=False))'),
  "workflows": { "1_left.jpg": "$W1", "0_left.jpg": "$W0" }
}
JSON

say ""
note "导出数据库观察快照…"
( cd "$REPO" && REAL_SERVICES_MYSQL_ADMIN_URL="$REAL_SERVICES_MYSQL_ADMIN_URL" \
    "$VENV_PY" scripts/acceptance_observe.py --run-id "$RUN_ID" ) || warn "观察快照导出失败（不影响已有证据）"

say ""
note "生成汇总报告…"
( cd "$REPO" && "$VENV_PY" scripts/accept_python_migration.py \
    --run-id "$RUN_ID" --phase summary ) || warn "summary 阶段返回非 0，看上面的输出"

SUMMARY=$(ls -t "$RUN_DIR"/*-summary-*/report.md 2>/dev/null | head -1 || true)
if [[ -n "$SUMMARY" ]]; then
  printf '  %s✓%s 报告：%s\n' "$GREEN" "$RESET" "${SUMMARY#$REPO/}"
fi
note "注意：acceptance_report.py 目前把 humanUI 固定写成 BLOCKED、标题固定写 BLOCKED。"
note "本轮证据已经落库，但要把结论改成 PASS 需要单独改代码并复核。"

finish
